    'ITAS',
    TRUE,
    $j$[{"category": "kitas_permits", "item_key": "E33G Remote Worker (Altus/Onshore)"}, {"category": "kitas_permits", "item_key": "E33G Remote Worker (Offshore)"}, {"category": "kitas_permits", "item_key": "E33G Remote Worker (Extend)"}]$j$::jsonb,
